SELECT c.*,s.market_end_at AS bound_market_end_at,s.condition_id AS bound_condition_id,s.selected_outcome_token_id AS bound_token,s.yes_token_id AS bound_yes_token,s.no_token_id AS bound_no_token,s.snapshot_id AS found_snapshot_id,s.event_slug,p.position_id AS found_position_id,p.phase AS position_phase,p.city AS position_city,p.target_date AS position_target_date,p.temperature_metric AS position_metric,p.condition_id AS position_condition_id FROM venue_commands c LEFT JOIN executable_market_snapshots s ON s.snapshot_id=c.snapshot_id LEFT JOIN position_current p ON p.position_id=c.position_id ORDER BY c.command_id;
SELECT command_id,event_id,sequence_no,event_type,occurred_at,state_after,CASE WHEN json_valid(payload_json) THEN json_extract(payload_json,'$.reason') END AS reason FROM venue_command_events ORDER BY command_id,sequence_no;
SELECT trade_fact_id,command_id,trade_id,venue_order_id,state,filled_size,observed_at,local_sequence FROM venue_trade_facts WHERE command_id IS NOT NULL;
SELECT fact_id,command_id,venue_order_id,state,matched_size,remaining_size,observed_at,local_sequence FROM venue_order_facts WHERE command_id IS NOT NULL;
